CREATE TABLE PUBLISHER (CODE CHAR(2) PRIMARY KEY, NAME VARCHAR(255), CAPTION VARCHAR(255));
CREATE TABLE GENRE (ID INT PRIMARY KEY, NAME VARCHAR(255), CAPTION VARCHAR(255));
CREATE TABLE GAME (
  PCODE CHAR(2) NOT NULL,
  GCODE CHAR(3) NOT NULL,
  GNAME VARCHAR(255) NOT NULL,
  GENREID INT,
  PRICE FLOAT,
  PRIMARY KEY (PCODE, GCODE),
  FOREIGN KEY (PCODE) REFERENCES PUBLISHER(CODE),
  FOREIGN KEY (GENREID) REFERENCES GENRE(ID)
);
